create extension if not exists pgtap with schema extensions;
begin;
select no_plan();
select set_config('t.a','90000000-0000-4000-8000-000000000001',true);
select set_config('t.b','90000000-0000-4000-8000-000000000002',true);
create function pg_temp.push_login(u uuid) returns void language plpgsql as $$ begin
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
end $$;
create function pg_temp.subscription(endpoint text default 'https://fcm.googleapis.com/fcm/send/test-browser') returns jsonb language sql as $$
 select jsonb_build_object('endpoint',endpoint,'keys',jsonb_build_object('p256dh',repeat('A',87),'auth',repeat('B',22)))
$$;
select ok(not has_table_privilege('authenticated','public.push_tokens','select'),'subscription secrets are not readable');
select ok(not has_function_privilege('authenticated','public.authorize_push_job_v1(uuid,uuid)','execute'),'users cannot retrieve worker secrets');
select ok(not has_function_privilege('anon','public.get_notification_preferences_v1()','execute'),'guests cannot read preferences');
select ok(not has_function_privilege('authenticated','private.notification_event(uuid,text,text,text,text,text,jsonb,timestamptz,text)','execute'),'event producer remains private');
select ok(private.valid_push_subscription(pg_temp.subscription()),'supported endpoint accepted');
select ok(not private.valid_push_subscription(pg_temp.subscription('https://fcm.googleapis.com.attacker.test/send')),'lookalike endpoint rejected');
select ok(not private.valid_push_subscription(pg_temp.subscription('https://fcm.googleapis.com@127.0.0.1/send')),'userinfo endpoint rejected');
select ok(not private.valid_push_subscription(pg_temp.subscription('http://fcm.googleapis.com/send')),'insecure endpoint rejected');
select ok(not private.valid_push_subscription(pg_temp.subscription()||'{"keys":{}}'),'missing encryption keys rejected');
select is(private.push_next_time('2026-10-17 22:30Z','Africa/Lagos','22:00','08:00'),'2026-10-18 07:00Z'::timestamptz,'overnight quiet hours defer to morning');
select is(private.push_next_time('2026-10-17 06:30Z','Africa/Lagos','22:00','08:00'),'2026-10-17 07:00Z'::timestamptz,'morning quiet hours end on same day');
select is(private.push_next_time('2026-10-17 08:00Z','Africa/Lagos','22:00','08:00'),'2026-10-17 08:00Z'::timestamptz,'outside quiet hours send now');
select is(private.push_next_time('2026-10-17 11:00Z','UTC','10:00','14:00'),'2026-10-17 14:00Z'::timestamptz,'same-day quiet interval supported');
select is(private.push_next_time('2026-03-08 06:00Z','America/New_York','22:00','08:00'),'2026-03-08 12:00Z'::timestamptz,'DST morning uses local timezone rules');
select pg_temp.push_login(current_setting('t.a')::uuid);
set local role authenticated;
select is(public.get_notification_preferences_v1()->'preferences'->>'reminder','false','reminders start off');
select is(public.get_notification_preferences_v1()->>'push_available','false','rollout starts disabled');
reset role;
select throws_ok($q$select public.register_push_token_v1('web','test-device-key',pg_temp.subscription())$q$,'PT403',null,'registration blocked outside rollout');
update private.push_control set enabled=true,general_release=true;
select public.register_push_token_v1('web','test-device-key',pg_temp.subscription());
select set_config('t.token',(select id::text from public.push_tokens where device_key='test-device-key' and user_id=current_setting('t.a')::uuid),true);
select throws_ok($q$select public.update_notification_preferences_v1('{"activity":true,"academic":true,"announcement":true,"account":true,"reminder":false,"timezone":"Invalid/Zone","reminder_time":"19:00","quiet_start":"22:00","quiet_end":"08:00"}')$q$,'PT422',null,'invalid timezone rejected');
select throws_ok($q$select public.update_notification_preferences_v1('{"activity":true,"academic":true,"announcement":true,"account":true,"reminder":false,"timezone":"UTC","reminder_time":"19:00","quiet_start":"08:00","quiet_end":"08:00"}')$q$,'PT422',null,'equal quiet boundaries rejected');
select throws_ok($q$select public.preview_announcement_v1('everyone')$q$,'PT403',null,'students cannot preview broadcast audience');
-- Ensure the current instant is outside quiet hours, regardless of test clock.
update private.notification_preferences set timezone='UTC',quiet_start=((now() at time zone 'UTC')+interval '1 hour')::time,quiet_end=((now() at time zone 'UTC')+interval '2 hours')::time;
select private.notification_event(current_setting('t.a')::uuid,'test','Test update','/home','push-test','activity');
select private.notification_event(current_setting('t.a')::uuid,'test','Test update','/home','push-test','activity');
select is((select count(*)::int from public.notifications where event_key='push-test'),1,'events deduplicated');
select is((select count(*)::int from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='push-test'),1,'one job per notification and subscription');
select set_config('t.job',(select id::text from private.push_jobs where token_id=current_setting('t.token')::uuid),true);
select public.claim_push_jobs_v1();
select set_config('t.lease',(select lease::text from private.push_jobs where id=current_setting('t.job')::uuid),true);
select is(jsonb_array_length(public.claim_push_jobs_v1()),0,'live leases cannot be claimed twice');
select ok(public.authorize_push_job_v1(current_setting('t.job')::uuid,current_setting('t.lease')::uuid) is not null,'eligible job authorized');
select public.finish_push_job_v1(current_setting('t.job')::uuid,current_setting('t.lease')::uuid,429,120);
select is((select state from private.push_jobs where id=current_setting('t.job')::uuid),'pending','rate limit retries');
select ok((select available_at>=now()+interval '120 seconds' from private.push_jobs where id=current_setting('t.job')::uuid),'provider retry-after respected');
update private.push_jobs set available_at=now() where id=current_setting('t.job')::uuid;
select public.claim_push_jobs_v1();
select set_config('t.lease',(select lease::text from private.push_jobs where id=current_setting('t.job')::uuid),true);
select public.finish_push_job_v1(current_setting('t.job')::uuid,gen_random_uuid(),201);
select is((select state from private.push_jobs where id=current_setting('t.job')::uuid),'sending','wrong lease cannot acknowledge');
update private.notification_preferences set activity=false where user_id=current_setting('t.a')::uuid;
select ok(public.authorize_push_job_v1(current_setting('t.job')::uuid,current_setting('t.lease')::uuid) is null,'changed category preference suppresses queued push');
select is((select state from private.push_jobs where id=current_setting('t.job')::uuid),'skipped','suppression recorded');
update private.notification_preferences set activity=true where user_id=current_setting('t.a')::uuid;
select private.notification_event(current_setting('t.a')::uuid,'test','Read update','/home','read-test','activity');
update public.notifications set read_at=now() where event_key='read-test';
select public.claim_push_jobs_v1();
select ok((select public.authorize_push_job_v1(j.id,j.lease) is null from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='read-test'),'read notification suppresses queued push');
select private.notification_event(current_setting('t.a')::uuid,'test','Expired update','/home','expired-test','activity','{}',now()-interval '1 second');
select public.prepare_push_batch_v1();
select is((select j.state from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='expired-test'),'expired','expired jobs are terminal');
select private.notification_event(current_setting('t.a')::uuid,'test','Accepted update','/home','accepted-test','activity');
select public.claim_push_jobs_v1();
select public.finish_push_job_v1(j.id,j.lease,201) from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='accepted-test';
select is((select j.state from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='accepted-test'),'accepted','provider acceptance recorded');
select private.notification_event(current_setting('t.a')::uuid,'test','Lease recovery','/home','lease-test','activity');
select public.claim_push_jobs_v1();
update private.push_jobs set lease_until=now()-interval '1 second' where notification_id in(select id from public.notifications where event_key='lease-test');
select is(jsonb_array_length(public.claim_push_jobs_v1()),1,'crashed worker lease recovered');
select public.finish_push_job_v1(j.id,j.lease,410) from private.push_jobs j join public.notifications n on n.id=j.notification_id where n.event_key='lease-test';
select ok((select revoked_at is not null and delivery_config='{}'::jsonb from public.push_tokens where id=current_setting('t.token')::uuid),'gone endpoint revoked and secrets cleared');
select ok(exists(select 1 from public.notifications where event_key='lease-test'),'push failure preserves inbox');
select public.register_push_token_v1('web','test-device-key',pg_temp.subscription());
select pg_temp.push_login(current_setting('t.b')::uuid);
select public.register_push_token_v1('web','other-device-key',pg_temp.subscription());
select ok((select revoked_at is not null from public.push_tokens where id=current_setting('t.token')::uuid),'account switch revokes previous subscription owner');
select throws_ok(format('select public.open_notification_v1(%L)',(select id from public.notifications where event_key='push-test')),'PT404',null,'another user cannot open notification');
select set_config('t.request',gen_random_uuid()::text,true);
select set_config('t.announcement',(public.send_announcement_v1('Test title','Plain text message','/home','everyone',null,current_setting('t.request')::uuid)->>'announcement_id'),true);
select is(public.send_announcement_v1('Test title','Plain text message','/home','everyone',null,current_setting('t.request')::uuid)->>'announcement_id',current_setting('t.announcement'),'announcement retry reuses snapshot');
select throws_ok($q$select public.send_announcement_v1('Changed','Message',null,'everyone',null,current_setting('t.request')::uuid)$q$,'PT422',null,'request key cannot change announcement');
select throws_ok($q$select public.send_announcement_v1('Title','Message','//attacker','everyone',null,gen_random_uuid())$q$,'PT422',null,'protocol-relative targets rejected');
select public.prepare_push_batch_v1();
select ok(exists(select 1 from public.notifications where event_key='announcement:'||current_setting('t.announcement')||':'||current_setting('t.a')),'announcement snapshot fans out to inbox');
select is(public.admin_push_health_v1()->>'delivery_enabled','true','admin can inspect aggregate health');
select pg_temp.push_login(current_setting('t.a')::uuid);
select throws_ok('select public.admin_push_health_v1()','PT403',null,'students cannot read delivery diagnostics');
-- Daily reminders use activity timestamps in each recipient's timezone.
select public.register_push_token_v1('web','reminder-device',pg_temp.subscription('https://fcm.googleapis.com/fcm/send/reminder'));
update private.notification_preferences set reminder=true,reminder_time='00:00',timezone='UTC' where user_id=current_setting('t.a')::uuid;
delete from public.activity_events where user_id=current_setting('t.a')::uuid;
select public.prepare_push_batch_v1();
select public.prepare_push_batch_v1();
select is((select count(*)::int from public.notifications where user_id=current_setting('t.a')::uuid and kind='study_reminder'),1,'one reminder per local day across repeated worker invocations');
insert into public.activity_events(user_id,kind,source_id,local_date) values(current_setting('t.a')::uuid,'lesson_completed',gen_random_uuid(),current_date);
select ok((select not private.push_relevant(n) from public.notifications n where n.user_id=current_setting('t.a')::uuid and kind='study_reminder'),'study after enqueue suppresses reminder');
update private.push_control set enabled=false;
select is(jsonb_array_length(public.claim_push_jobs_v1()),0,'kill switch blocks delivery claims');
select pg_temp.push_login(current_setting('t.b')::uuid);
select lives_ok($q$select public.send_announcement_v1('Paused','Inbox still works',null,'everyone',null,gen_random_uuid())$q$,'announcements continue while delivery paused');
select public.prepare_push_batch_v1();
select ok(exists(select 1 from public.notifications where body='Inbox still works'),'kill switch preserves inbox fan-out');
-- Activity event producers are transactional and idempotent.
select pg_temp.push_login(current_setting('t.a')::uuid);
select public.friend_action_v1(current_setting('t.b')::uuid,'request');
select public.friend_action_v1(current_setting('t.b')::uuid,'request');
select is((select count(*)::int from public.notifications where user_id=current_setting('t.b')::uuid and kind='friend_request'),1,'friend requests notify exactly once');
select pg_temp.push_login(current_setting('t.b')::uuid);
select public.friend_action_v1(current_setting('t.a')::uuid,'accept');
select public.friend_action_v1(current_setting('t.a')::uuid,'accept');
select is((select count(*)::int from public.notifications where user_id=current_setting('t.a')::uuid and kind='friend_accepted'),1,'friend acceptance notifies exactly once');
select ok((select not private.push_relevant(n) from public.notifications n where user_id=current_setting('t.b')::uuid and kind='friend_request'),'accepted request is no longer actionable');
update private.push_control set announcement_hourly_limit=1;
select throws_ok($q$select public.send_announcement_v1('Limit','Message',null,'everyone',null,gen_random_uuid())$q$,'PT429',null,'announcement limit enforced transactionally');
-- A normal student cannot use an offering identifier to bypass lecturer authorization.
select pg_temp.push_login(current_setting('t.a')::uuid);
select throws_ok($q$select public.preview_announcement_v1('offering','20000000-0000-4000-8000-000000000002')$q$,'PT403',null,'student cannot announce to an enrolled offering');
select public.revoke_push_token_v1('web','reminder-device');
select ok((select delivery_config='{}'::jsonb from public.push_tokens where device_key='reminder-device'),'explicit revocation clears subscription secrets');
-- Existing course publication markers survive fan-out retention and block edits being reannounced.
select ok(exists(select 1 from private.lesson_notification_publications),'published lessons receive durable markers');
select ok(exists(select 1 from private.assessment_notification_publications),'published assessments receive durable markers');
select set_config('t.new_lesson',gen_random_uuid()::text,true);
select set_config('t.new_version',gen_random_uuid()::text,true);
insert into public.lessons(id,course_id,module_id,position)
select current_setting('t.new_lesson')::uuid,l.course_id,l.module_id,(select max(position)+10 from public.lessons where module_id=l.module_id)
from public.lessons l join public.lesson_versions v on v.lesson_id=l.id where v.id='23000000-0000-4000-8000-000000000001';
insert into public.lesson_versions(id,lesson_id,version,title,objective,blocks,estimated_minutes,source_reference)
select current_setting('t.new_version')::uuid,current_setting('t.new_lesson')::uuid,1,title,objective,blocks,estimated_minutes,source_reference
from public.lesson_versions where id='23000000-0000-4000-8000-000000000001';
select private.publish_lesson_version(current_setting('t.new_version')::uuid,current_setting('t.b')::uuid);
select ok(exists(select 1 from private.notification_recipients where event_key='lesson_published:'||current_setting('t.new_lesson')),'first publication snapshots enrolled recipients');
delete from private.notification_recipients where event_key='lesson_published:'||current_setting('t.new_lesson');
update public.lesson_versions set status='retired',retired_at=now(),retired_by=current_setting('t.b')::uuid,retired_reason='superseded' where id=current_setting('t.new_version')::uuid;
select set_config('t.new_version2',gen_random_uuid()::text,true);
insert into public.lesson_versions(id,lesson_id,version,title,objective,blocks,estimated_minutes,source_reference)
select current_setting('t.new_version2')::uuid,lesson_id,2,title,objective,blocks,estimated_minutes,source_reference from public.lesson_versions where id=current_setting('t.new_version')::uuid;
select private.publish_lesson_version(current_setting('t.new_version2')::uuid,current_setting('t.b')::uuid);
select is((select count(*)::int from private.notification_recipients where event_key='lesson_published:'||current_setting('t.new_lesson')),0,'replacement publication does not resend after snapshot retention');
update public.profiles set deactivated_at=now() where id=current_setting('t.a')::uuid;
select ok(not exists(select 1 from public.push_tokens where user_id=current_setting('t.a')::uuid and revoked_at is null),'deactivation revokes devices');
delete from auth.users where id=current_setting('t.a')::uuid;
select ok(not exists(select 1 from private.push_jobs where user_id=current_setting('t.a')::uuid),'erasure cascades delivery jobs');
select ok(not exists(select 1 from private.notification_preferences where user_id=current_setting('t.a')::uuid),'erasure cascades preferences');
select * from finish();
rollback;
